import { FC, useLayoutEffect, useMemo, useRef, useState, CSSProperties } from 'react';
import { useMediaQuery } from '@mui/material';
import { ITheme } from '.';
import {
  formatPortfolioValueDisplay,
  normalizePortfolioMultilineText,
  PORTFOLIO_BAR_CHART_LABEL_BAR_GAP_PX,
  PORTFOLIO_BAR_CHART_LABEL_COLUMN_FALLBACK_PX,
  PORTFOLIO_BAR_CHART_REFERENCE_LABELS,
  PORTFOLIO_BAR_CHART_RIGHT_MARGIN_PX,
  PORTFOLIO_FONT_FAMILY,
  PORTFOLIO_TEXT_COLOR,
  PORTFOLIO_WIDGET_FONT_SIZE_PX,
  portfolioBarChartLabelText,
} from '../../../contants/portfolioTypography';

type CellStyle = { bold?: boolean; italic?: boolean; underline?: boolean };

type Props = {
  color: string;
  content: {
    title?: string;
    categories: string[];
    chartData: {
      name: string;
      data: number[];
    }[];
    isPercent?: boolean;
    barColorSets?: string[];
    categoryStyles?: CellStyle[];
    valueStyles?: CellStyle[];
    /** Excel value strings parallel to `categories` — used for per-cell decimal display. */
    rawValues?: string[];
    /**
     * Optional decimals override from the config sheet (slot A1 / A2 / …).
     * `undefined` → keep legacy display (up to 2 decimals, trailing zeros stripped).
     */
    decimals?: number;
  };
  theme?: ITheme;
};

/**
 * German-formatted percent. When `decimals` is set, the value is rounded / padded
 * to exactly that many decimal places ("21,00%", "3%"); otherwise it falls back to
 * the legacy behavior of up to 2 decimals with trailing zeros stripped.
 */
function formatPercent(rawValue: string, numericValue: number, decimals?: number): string {
  const raw = rawValue.trim();
  if (raw) return formatPortfolioValueDisplay(raw, decimals);
  if (!Number.isFinite(numericValue)) return '0%';
  return formatPortfolioValueDisplay(`${numericValue}%`, decimals);
}

/** Non-percent raw number (rare on SQUAD portfolio) with the same decimals contract. */
function formatNumber(value: number, decimals?: number): string {
  if (!Number.isFinite(value)) return '';
  if (decimals != null && Number.isFinite(decimals) && decimals >= 0) {
    return value.toFixed(decimals).replace('.', ',');
  }
  return `${value}`;
}

/** Preserve Excel Alt+Enter; only normalize line-ending variants. */
function normalizeBarCategoryLabel(label: string): string {
  return normalizePortfolioMultilineText(label);
}

function cellStyleToCss(style?: CellStyle): CSSProperties {
  return {
    fontWeight: style?.bold ? 700 : 400,
    fontStyle: style?.italic ? 'italic' : 'normal',
    textDecoration: style?.underline ? 'underline' : 'none',
  };
}

/** Min bar width (% of track) before attempting an inside label. */
const VALUE_INSIDE_MIN_BAR_PCT = 20;

/**
 * Inside labels need room for the formatted text + padding.
 * Prevents clipped values like ",92%" on narrow bars at the 20% threshold.
 */
function shouldShowValueInside(barPct: number, formattedValue: string): boolean {
  if (barPct < VALUE_INSIDE_MIN_BAR_PCT) return false;
  const minPctForText = (formattedValue.length + 2) * 3;
  return barPct >= Math.max(VALUE_INSIDE_MIN_BAR_PCT + 4, minPctForText);
}

/**
 * Manual horizontal bar chart for SQUAD CSV portfolio.
 * - Label column: fixed width for 30 characters at 14px, right-aligned.
 * - Bar track: remaining width minus a fixed right margin (static per widget).
 * - Labels wrap at 30 characters; Excel Alt+Enter preserved via `pre-line`.
 */
export const CustomPortfolioBarChart: FC<Props> = ({ color, content, theme }) => {
  const isCompact = useMediaQuery('(max-width: 600px)');
  const measureRef = useRef<HTMLSpanElement>(null);
  const [labelColumnWidthPx, setLabelColumnWidthPx] = useState(
    PORTFOLIO_BAR_CHART_LABEL_COLUMN_FALLBACK_PX
  );

  useLayoutEffect(() => {
    const el = measureRef.current;
    if (!el) return;
    let max = 0;
    for (const text of PORTFOLIO_BAR_CHART_REFERENCE_LABELS) {
      el.textContent = text;
      max = Math.max(max, el.offsetWidth);
    }
    if (max > 0) setLabelColumnWidthPx(max);
  }, []);
  const seriesData = content?.chartData?.[0]?.data ?? [];
  const categories = useMemo(
    () => (content?.categories ?? []).map(normalizeBarCategoryLabel),
    [content?.categories]
  );

  const maxValue = useMemo(() => {
    const max = Math.max(0, ...seriesData);
    return Number.isFinite(max) && max > 0 ? max : 0;
  }, [seriesData]);

  /** Theme stores [primary, secondary] per row; bar chart uses primary (index 0) only. */
  const barColor = useMemo(() => {
    const fromSets = Array.isArray(content?.barColorSets) ? content.barColorSets.filter(Boolean) : [];
    const fromTheme = (theme?.colorSet?.gradientColors || []).filter(Boolean) as string[];
    const palette = fromSets.length > 0 ? fromSets : fromTheme;
    const fallback = theme?.colorSet?.primary || color;
    return palette[0] || fallback;
  }, [content?.barColorSets, theme?.colorSet?.gradientColors, theme?.colorSet?.primary, color]);

  const rows = useMemo(
    () =>
      categories.map((label, idx) => {
        const value = Number(seriesData[idx] ?? 0);
        const pct = maxValue > 0 ? (value / maxValue) * 100 : 0;
        return {
          label,
          value,
          pct: Math.max(0, Math.min(100, pct)),
          labelStyle: content?.categoryStyles?.[idx],
          valueStyle: content?.valueStyles?.[idx],
        };
      }),
    [categories, seriesData, maxValue, content?.categoryStyles, content?.valueStyles]
  );

  const desktopGridColumns = `${labelColumnWidthPx}px minmax(0, 1fr)`;

  return (
    <div
      className="custom-portfolio-bar-chart"
      lang="de"
      style={{
        width: '100%',
        maxWidth: '100%',
        minWidth: 0,
        boxSizing: 'border-box',
        overflow: 'hidden',
        fontFamily: PORTFOLIO_FONT_FAMILY,
        color: PORTFOLIO_TEXT_COLOR,
        fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
        paddingRight: isCompact ? 0 : PORTFOLIO_BAR_CHART_RIGHT_MARGIN_PX,
        position: 'relative',
      }}
    >
      <span
        ref={measureRef}
        aria-hidden
        style={{
          position: 'absolute',
          visibility: 'hidden',
          whiteSpace: 'nowrap',
          fontFamily: PORTFOLIO_FONT_FAMILY,
          fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
          pointerEvents: 'none',
          left: 0,
          top: 0,
        }}
      />
      {rows.map((row, idx) => {
        const isPercent = Boolean(content?.isPercent);
        const rawValue = content?.rawValues?.[idx] ?? '';
        const formattedValue = isPercent
          ? formatPercent(rawValue, row.value, content?.decimals)
          : formatNumber(row.value, content?.decimals);

        const valueInside = shouldShowValueInside(row.pct, formattedValue);

        const rowLayout: CSSProperties = isCompact
          ? {
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'stretch',
              gap: 4,
            }
          : {
              display: 'grid',
              gridTemplateColumns: desktopGridColumns,
              alignItems: 'center',
              columnGap: PORTFOLIO_BAR_CHART_LABEL_BAR_GAP_PX,
            };

        return (
          <div
            key={idx}
            className="cpc-row"
            style={{
              ...rowLayout,
              minHeight: isCompact ? undefined : 28,
              paddingTop: 3,
              paddingBottom: 3,
              width: '100%',
              maxWidth: '100%',
              minWidth: 0,
              boxSizing: 'border-box',
            }}
          >
            <div
              className="cpc-category"
              title={row.label}
              style={{
                lineHeight: 1.25,
                width: isCompact ? '100%' : labelColumnWidthPx,
                maxWidth: isCompact ? '100%' : labelColumnWidthPx,
                minWidth: 0,
                flexShrink: 0,
                justifySelf: isCompact ? 'stretch' : 'end',
                boxSizing: 'border-box',
                ...cellStyleToCss(row.labelStyle),
                textAlign: 'right',
                whiteSpace: 'pre-line',
              }}
            >
              {portfolioBarChartLabelText(row.label)}
            </div>

            <div
              className="cpc-bar-track"
              style={{
                position: 'relative',
                width: '100%',
                height: 22,
                display: 'flex',
                alignItems: 'center',
                overflow: 'visible',
                minWidth: 0,
              }}
            >
              <div
                className="cpc-bar-fill"
                style={{
                  width: `${row.pct}%`,
                  flexShrink: 0,
                  height: '100%',
                  backgroundColor: barColor,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'flex-end',
                  paddingRight: valueInside ? 8 : 0,
                  paddingLeft: valueInside ? 4 : 0,
                  boxSizing: 'border-box',
                  minWidth: valueInside ? undefined : row.value > 0 ? 1 : 0,
                  overflow: valueInside ? 'hidden' : undefined,
                }}
              >
                {valueInside && (
                  <span
                    style={{
                      color: PORTFOLIO_TEXT_COLOR,
                      fontWeight: 700,
                      fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
                      whiteSpace: 'nowrap',
                      ...cellStyleToCss(row.valueStyle),
                    }}
                  >
                    {formattedValue}
                  </span>
                )}
              </div>
              {!valueInside && (
                <span
                  className="cpc-value-outside"
                  style={{
                    marginLeft: 8,
                    color: PORTFOLIO_TEXT_COLOR,
                    fontWeight: 700,
                    fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
                    whiteSpace: 'nowrap',
                    flexShrink: 0,
                    ...cellStyleToCss(row.valueStyle),
                  }}
                >
                  {formattedValue}
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};
