function parseNum(value: unknown): number {
  if (value == null) return 0;
  const s = String(value).replace(/\s/g, '').replace(',', '.');
  const n = parseFloat(s.replace(/[^\d.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

/** Widget slot code (A1, A2, …, D2) for a given section / widget position. */
function widgetSlotCode(sectionIndex: number, widgetIndex: number): string {
  // 26 section rows is more than enough for any realistic portfolio; fall back to "?" above that.
  const letter = sectionIndex >= 0 && sectionIndex < 26
    ? String.fromCharCode('A'.charCodeAt(0) + sectionIndex)
    : '?';
  return `${letter}${widgetIndex + 1}`;
}

function isEmptyArt(art?: string): boolean {
  return String(art ?? '')
    .trim()
    .toLowerCase() === 'empty';
}

function isTableArt(art?: string): boolean {
  const a = String(art ?? '').trim().toLowerCase();
  return a.includes('table') || a.includes('tabelle');
}

function artToType(art: string): 'pie-chart' | 'bar-chart' | 'table' | 'empty' {
  if (isEmptyArt(art)) return 'empty';
  const a = (art || '').toLowerCase();
  if (isTableArt(art)) return 'table';
  if (a.includes('pie')) return 'pie-chart';
  if (a.includes('bar')) return 'bar-chart';
  return 'pie-chart';
}

type WidgetRow = { label: string; value: string; labelL?: string; isTemplateLastDataRow?: boolean };
type CellStyle = { bold?: boolean; italic?: boolean; underline?: boolean };
type StyledWidgetRow = WidgetRow & { labelStyle?: CellStyle; valueStyle?: CellStyle; labelLStyle?: CellStyle };

type FootnoteRun = { text: string; bold?: boolean; italic?: boolean; underline?: boolean };

type PortfolioWidget = {
  title?: string;
  art?: string;
  sortierung?: string;
  rows?: WidgetRow[];
  footnote?: string;
  footnoteRuns?: FootnoteRun[];
  /** True when the fixed template last data row (`dataEndRow`) has a real entry. */
  lastRowHasEntry?: boolean;
  /** Config sheet ja=1 — enables pin (pie/bar sort) and table header on the 16th data row. */
  lastRowForCashOrHeader?: number;
  /** Index into `rows` for that template last row when `lastRowHasEntry` is true. */
  pinnedDataRowIndex?: number;
  /** Label from the fixed 16th data row on the sheet (when `lastRowHasEntry`). */
  templateLastRowLabel?: string;
  templateLastRowValue?: string;
  /** Per-widget "Wert (max. Zeichen)" from the portfolio sheet — decimal places for display. */
  valueMaxChars?: number;
};
type PortfolioWidgetSection = { sectionTitle?: string; widgets?: PortfolioWidget[] };

type SectionFootnoteBlock =
  | { kind: 'runs'; key: string; runs: FootnoteRun[] }
  | { kind: 'plain'; key: string; text: string };

function normalizeWidgetFootnotePlain(footnote: unknown): string {
  return String(footnote ?? '')
    .replace(/_x000D_/g, '\n')
    .replace(/\r\n?/g, '\n');
}

/**
 * Prepare footnote for display: keep Alt+Enter breaks and blank lines; only remove
 * merged-cell duplicates (exact repeat, or consecutive duplicate Quelle/Fußnote lines).
 */
function formatFootnoteForDisplay(text: string): string {
  let t = normalizeWidgetFootnotePlain(text);
  if (!t) return t;

  const half = Math.floor(t.length / 2);
  if (half > 24 && t.slice(0, half) === t.slice(half)) {
    t = t.slice(0, half);
  }

  const lines = t.split('\n');
  const out: string[] = [];
  let prevNorm = '';
  for (const line of lines) {
    const norm = line.replace(/\s+/g, ' ').trim().toLowerCase();
    if (
      norm &&
      norm === prevNorm &&
      (norm.includes('quelle') || norm.includes('fußnote') || norm.includes('fussnote'))
    ) {
      continue;
    }
    out.push(line);
    prevNorm = norm;
  }
  return out.join('\n');
}

function footnoteDedupeSemanticKey(text: string): string {
  return formatFootnoteForDisplay(text).toLowerCase().replace(/\s+/g, ' ').trim();
}

/** Dedupe the same footnote across left/right splitted widgets (plain or rich). */
function collectSectionFootnoteBlocks(widgets: PortfolioWidget[]): SectionFootnoteBlock[] {
  const seen = new Set<string>();
  const out: SectionFootnoteBlock[] = [];
  for (const w of widgets) {
    if (isEmptyArt(w?.art)) continue;
    const runs = w.footnoteRuns;
    if (Array.isArray(runs) && runs.length > 0) {
      const joined = formatFootnoteForDisplay(runs.map((x) => x.text).join(''));
      const key = footnoteDedupeSemanticKey(joined);
      if (!joined || seen.has(key)) continue;
      seen.add(key);
      const hasStyle = runs.some((x) => x.bold || x.italic || x.underline);
      if (hasStyle) {
        out.push({
          kind: 'runs',
          key,
          runs: runs.map((r) => ({ ...r, text: normalizeWidgetFootnotePlain(r.text) })),
        });
      } else {
        out.push({ kind: 'plain', key, text: joined });
      }
      continue;
    }
    const text = formatFootnoteForDisplay(w?.footnote ?? '');
    if (!text) continue;
    const key = footnoteDedupeSemanticKey(text);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ kind: 'plain', key, text });
  }
  return out;
}

function FootnoteRuns({ runs }: { runs: FootnoteRun[] }) {
  return (
    <>
      {runs.map((run, j) => (
        <span
          key={j}
          style={{
            fontWeight: run.bold ? 700 : undefined,
            fontStyle: run.italic ? 'italic' : undefined,
            textDecoration: run.underline ? 'underline' : undefined,
          }}
        >
          {run.text}
        </span>
      ))}
    </>
  );
}

/** Template control row "Summe (Kontrollwert)" — not data labels like "Summe der 10". */
function isSumRow(row: StyledWidgetRow): boolean {
  const s = String(row?.label || '').trim().toLowerCase();
  if (s.includes('kontrollwert')) return true;
  return /^summe\s*\(/.test(s);
}

function isTemplateHeaderRow(row: StyledWidgetRow): boolean {
  const label = String(row?.label || '').trim().toLowerCase();
  const value = String(row?.value || '').trim().toLowerCase();
  if (!label && !value) return false;
  const isLabelHeader = label === 'label';
  const isValueHeader = value === 'value' || value === 'wert';
  return isLabelHeader && isValueHeader;
}

function isSameDataRow(a: StyledWidgetRow, b: StyledWidgetRow): boolean {
  return (
    String(a?.label ?? '').trim() === String(b?.label ?? '').trim() &&
    String(a?.value ?? '').trim() === String(b?.value ?? '').trim()
  );
}

function normalizeSortMode(sortierung?: string): 'default' | 'label-asc' | 'label-desc' | 'value-asc' | 'value-desc' {
  const raw = (sortierung || '').trim().toLowerCase().replace(/\s+/g, '-').replace(/_/g, '-');
  if (!raw) return 'default';

  // common typo from templates: "lable-asc/desc"
  if (raw === 'lable-asc') return 'label-asc';
  if (raw === 'lable-desc') return 'label-desc';

  if (raw === 'label-asc' || raw === 'label-desc' || raw === 'value-asc' || raw === 'value-desc' || raw === 'default') {
    return raw;
  }
  return 'default';
}

/** Pure sort (no pinning). Summe (Kontrollwert) rows are always appended at the end. */
function sortRowsPure(rows: StyledWidgetRow[], sortierung?: string): StyledWidgetRow[] {
  const mode = normalizeSortMode(sortierung);
  const sumRows = rows.filter(isSumRow);
  const baseRows = rows.filter((r) => !isSumRow(r));
  if (mode === 'default') return [...baseRows, ...sumRows];

  const sorted = [...baseRows];
  if (mode === 'value-asc') {
    sorted.sort((a, b) => parseNum(a.value) - parseNum(b.value));
  } else if (mode === 'value-desc') {
    sorted.sort((a, b) => parseNum(b.value) - parseNum(a.value));
  } else if (mode === 'label-asc') {
    sorted.sort((a, b) =>
      String(a.label || '').localeCompare(String(b.label || ''), 'de', { sensitivity: 'base' })
    );
  } else if (mode === 'label-desc') {
    sorted.sort((a, b) =>
      String(b.label || '').localeCompare(String(a.label || ''), 'de', { sensitivity: 'base' })
    );
  }
  return [...sorted, ...sumRows];
}

function sortRowsByMode(
  rows: StyledWidgetRow[],
  sortierung?: string,
  /** Index into `rows` for the template fixed last data row; omit for no pinning. */
  pinnedRowIndex?: number
): StyledWidgetRow[] {
  const mode = normalizeSortMode(sortierung);
  const sumRows = rows.filter(isSumRow);
  const baseRows = rows.filter((r) => !isSumRow(r));

  const pinnedCandidate =
    pinnedRowIndex != null && pinnedRowIndex >= 0 && pinnedRowIndex < rows.length
      ? rows[pinnedRowIndex]
      : null;
  const hasPin = Boolean(
    pinnedCandidate && !isSumRow(pinnedCandidate) && !isTemplateHeaderRow(pinnedCandidate)
  );
  const pinned = hasPin ? pinnedCandidate : null;
  const isNotPinned = (r: StyledWidgetRow) =>
    !pinned || (r !== pinned && !isSameDataRow(r, pinned));

  // Default: optional pin — keep sheet order for other rows, fixed last row at bottom.
  if (mode === 'default') {
    if (pinned) {
      const sortable = baseRows.filter(isNotPinned);
      return [...sortable, pinned, ...sumRows];
    }
    return rows;
  }

  if (!pinned) {
    return sortRowsPure(rows, sortierung);
  }

  const sortable = baseRows.filter(isNotPinned);
  if (sortable.length === 0) return [...baseRows, ...sumRows];

  if (mode === 'value-asc') {
    sortable.sort((a, b) => parseNum(a.value) - parseNum(b.value));
  } else if (mode === 'value-desc') {
    sortable.sort((a, b) => parseNum(b.value) - parseNum(a.value));
  } else if (mode === 'label-asc') {
    sortable.sort((a, b) =>
      String(a.label || '').localeCompare(String(b.label || ''), 'de', { sensitivity: 'base' })
    );
  } else if (mode === 'label-desc') {
    sortable.sort((a, b) =>
      String(b.label || '').localeCompare(String(a.label || ''), 'de', { sensitivity: 'base' })
    );
  } else {
    return sortRowsPure(rows, sortierung);
  }

  return [...sortable, pinned, ...sumRows];
}

/** Excel "Letzte Zeile für … (ja=1)" — when 0, all 16 data rows stay in the table body. */
function isLastRowPinEnabled(w: PortfolioWidget): boolean {
  return w.lastRowForCashOrHeader !== 0;
}

/**
 * Index of the template fixed last data row (16th slot / `dataEndRow`) inside `rows`.
 * Prefer `isTemplateLastDataRow` (independent of `lastRowHasEntry` for patched API responses).
 * Legacy uploads fall back to `pinnedDataRowIndex` only when no row carries the marker.
 */
function resolveChartPinnedRowIndex(w: PortfolioWidget, rows: StyledWidgetRow[]): number {
  if (!isLastRowPinEnabled(w)) return -1;
  if (w.lastRowHasEntry === false) return -1;

  const acceptPin = (idx: number): number => {
    if (idx < 0 || idx >= rows.length) return -1;
    const candidate = rows[idx];
    if (!candidate || isSumRow(candidate) || isTemplateHeaderRow(candidate)) return -1;
    return idx;
  };

  const markedIdx = rows.findIndex((r) => r.isTemplateLastDataRow === true);
  if (markedIdx >= 0) return acceptPin(markedIdx);

  const slotLabel = (w.templateLastRowLabel || '').trim();
  if (w.lastRowHasEntry === true && slotLabel) {
    const byLabel = rows.findIndex((r) => String(r.label || '').trim() === slotLabel);
    const fromSlot = acceptPin(byLabel);
    if (fromSlot >= 0) return fromSlot;
  }

  const hasMarkerField = rows.some((r) => Object.prototype.hasOwnProperty.call(r, 'isTemplateLastDataRow'));
  if (hasMarkerField) return -1;

  if (w.lastRowHasEntry !== true) return -1;

  const idx = w.pinnedDataRowIndex;
  if (typeof idx !== 'number') return -1;
  return acceptPin(idx);
}

/** Table: promote template last data row (e.g. Excel line 91) to header when that row exists — same as chart pin resolution, not gated on Excel ja=1. */
function resolveTablePinnedRowIndex(w: PortfolioWidget, rows: StyledWidgetRow[]): number {
  return resolveChartPinnedRowIndex(w, rows);
}

function getRenderableRowsByType(
  rows: StyledWidgetRow[],
  type: 'pie-chart' | 'bar-chart' | 'table'
): StyledWidgetRow[] {
  if (type === 'table') {
    return rows.filter((r) => !isSumRow(r) && !isTemplateHeaderRow(r) && (r.label || r.value));
  }
  return rows.filter((r) => r.label && !isSumRow(r));
}

function widgetHasRenderableContent(w: PortfolioWidget): boolean {
  if (isEmptyArt(w.art)) return false;
  const rows: StyledWidgetRow[] = Array.isArray(w.rows) ? w.rows : [];
  const type = artToType((w.art || 'Pie Chart').trim());
  if (type === 'empty') return false;
  return getRenderableRowsByType(rows, type).length > 0;
}

function toPieChartContent(rows: StyledWidgetRow[], decimals?: number) {
  const chartData = rows
    .filter((r) => r.label && !isSumRow(r))
    .map((r) => ({
      label: normalizePortfolioMultilineText(r.label),
      value: parseNum(r.value),
      rawValue: String(r.value ?? ''),
      labelStyle: r.labelStyle || {},
      valueStyle: r.valueStyle || {},
    }));
  return {
    // Hide per-widget sub label above pie chart (e.g. "Restlaufzeiten", "Allokation")
    // and keep only the section title rendered by PortfolioSection.
    title: '',
    showBlocks: false,
    chartData,
    ...(decimals != null && { decimals }),
  };
}

function toBarChartContent(
  rows: StyledWidgetRow[],
  title?: string,
  barColorSets?: string[],
  decimals?: number
) {
  const filtered = rows.filter((r) => r.label && !isSumRow(r));
  const categories = filtered.map((r) => normalizePortfolioMultilineText(r.label));
  const rawValues = filtered.map((r) => String(r.value ?? ''));
  const chartData = [{ name: 'Value', data: filtered.map((r) => parseNum(r.value)) }];
  return {
    title: title || '',
    chartData,
    categories,
    rawValues,
    isPercent: true,
    chartType: 'Manuall',
    isin: '',
    color: '',
    categoryStyles: filtered.map((r) => r.labelStyle || {}),
    valueStyles: filtered.map((r) => r.valueStyle || {}),
    ...(barColorSets && barColorSets.length > 0 && { barColorSets }),
    ...(decimals != null && { decimals }),
  };
}

/**
 * Custom portfolio table: when the template last data row exists (e.g. "Letzte Zeile" on row 31),
 * that row becomes the column header (bold). Body rows above it are sorted; Summe rows trail the body.
 */
function toTableContent(
  rows: StyledWidgetRow[],
  sortierung?: string,
  decimals?: number,
  pinnedRowIndex?: number
) {
  const fmt = (v: unknown) => formatPortfolioValueDisplay(v, decimals);
  const emptyContent = {
    title: '',
    type: 'Manual',
    isin: '',
    themeIndex: 2,
    body: [] as { text: string; style: CellStyle }[][],
    header: ['Label', 'Value'],
    showHeader: true,
    columns: [
      { type: 'text', showColumnTooltip: false, showValueConfiguration: false, columnTooltip: '' },
      { type: 'text', showColumnTooltip: false, showValueConfiguration: false, columnTooltip: '' },
    ],
  };

  if (rows.length === 0) return emptyContent;

  const sumRows = rows.filter(isSumRow);
  const nonSumRows = rows.filter((r) => !isSumRow(r));
  const dataRows = nonSumRows.filter((r) => !isTemplateHeaderRow(r));

  if (dataRows.length === 0) {
    // No real data rows: keep the widget empty (same expectation as pie/bar).
    return {
      ...emptyContent,
      showHeader: false,
      body: [],
    };
  }

  const pinnedRow =
    pinnedRowIndex != null && pinnedRowIndex >= 0 && pinnedRowIndex < rows.length
      ? rows[pinnedRowIndex]
      : null;
  const pinValid = Boolean(
    pinnedRow && !isSumRow(pinnedRow) && !isTemplateHeaderRow(pinnedRow)
  );

  const bodyRows =
    pinValid && pinnedRow
      ? dataRows.filter((r) => r !== pinnedRow && !isSameDataRow(r, pinnedRow))
      : dataRows;
  const sortedBody = sortRowsPure(bodyRows, sortierung);

  const headerBold = (base?: CellStyle): CellStyle => ({
    ...(base || {}),
    bold: true,
  });
  const header =
    pinValid && pinnedRow
      ? [
          {
            text: normalizePortfolioMultilineText(String(pinnedRow.label ?? '')),
            style: headerBold(pinnedRow.labelStyle),
          },
          { text: fmt(pinnedRow.value ?? '').trim(), style: headerBold(pinnedRow.valueStyle) },
        ]
      : ['', ''];
  const body = [...sortedBody, ...sumRows].map((r) => [
    { text: normalizePortfolioMultilineText(r.label), style: r.labelStyle || {} },
    { text: fmt(r.value), style: r.valueStyle || {} },
  ]);

  return {
    title: '',
    type: 'Manual',
    isin: '',
    themeIndex: 2,
    body,
    header,
    showHeader: pinValid,
    columns: [
      { type: 'text', showColumnTooltip: false, showValueConfiguration: false, columnTooltip: '' },
      { type: 'text', showColumnTooltip: false, showValueConfiguration: false, columnTooltip: '' },
    ],
  };
}

type PortfolioTheme = {
  pieCharts?: { fund: string; colors: string[] }[];
  barCharts?: { fund: string; colors: string[] }[];
  fsHeader?: { fund: string; colors: string[] }[];
  /**
   * Decimals override grid from the config sheet (rows 38-41, columns G/H + I/J).
   * Slot codes are A1/A2/B1/B2/C1/C2/D1/D2 (row letter = section index, 1=left, 2=right).
   * An unset slot means "leave values as pasted".
   */
  decimalsConfig?: Record<string, number>;
};

/** Resolve color set: portfolio Farbtheme (B4) first, then widget title, then first config row. */
function getPieColorsFromTheme(
  theme: PortfolioTheme | null,
  portfolioFarbthemeFund: string,
  fallbackWidgetTitle: string
): string[] | undefined {
  const list = theme?.pieCharts;
  if (!Array.isArray(list) || list.length === 0) return undefined;
  const keys = [portfolioFarbthemeFund, fallbackWidgetTitle]
    .map((k) => (k || '').trim().toLowerCase())
    .filter(Boolean);
  for (const key of keys) {
    const match = list.find((e) => (e.fund || '').trim().toLowerCase() === key);
    if (match && Array.isArray(match.colors) && match.colors.length > 0) return match.colors;
  }
  return list[0]?.colors;
}

function getBarColorsFromTheme(
  theme: PortfolioTheme | null,
  portfolioFarbthemeFund: string,
  fallbackWidgetTitle: string
): string[] | undefined {
  const list = theme?.barCharts;
  if (!Array.isArray(list) || list.length === 0) return undefined;
  const keys = [portfolioFarbthemeFund, fallbackWidgetTitle]
    .map((k) => (k || '').trim().toLowerCase())
    .filter(Boolean);
  for (const key of keys) {
    const match = list.find((e) => (e.fund || '').trim().toLowerCase() === key);
    if (match && Array.isArray(match.colors) && match.colors.length > 0) return match.colors;
  }
  return list[0]?.colors;
}

type CustomPortfolioContent = {
  portfolioUploadId?: string;
  isins?: string[];
  /** @deprecated No longer used; all widgets from the selected portfolio are shown. */
  portfolioWidgetKey?: string;
};

type Props = {
  content: CustomPortfolioContent;
  color: string;
  theme?: ITheme;
  isin: string;
};

/** Renders a single portfolio section (one widget item with section title + 1 or 2 splitted widgets). */
function PortfolioSection({
  widgetItem,
  sectionIndex,
  parsedTheme,
  farbthemeFund,
  standDerDaten,
  color,
  theme,
  isin,
  isNarrow,
}: {
  widgetItem: PortfolioWidgetSection;
  /** 0-based section position; drives the slot-letter (0 = A, 1 = B, …) for the decimals override. */
  sectionIndex: number;
  parsedTheme: PortfolioTheme | null;
  /** From portfolio sheet B4 (Farbtheme); drives which config-sheet fund row supplies colors. */
  farbthemeFund: string;
  /** Portfolio sheet B3 — shown as “Stand: …” under each section headline. */
  standDerDaten?: string | null;
  color: string;
  theme?: ITheme;
  isin: string;
  isNarrow: boolean;
}) {
  const sectionTitle = widgetItem.sectionTitle || '';
  const widgets: PortfolioWidget[] = Array.isArray(widgetItem.widgets) ? widgetItem.widgets : [];
  const renderableWidgets = widgets.filter(widgetHasRenderableContent);
  const hasExplicitEmptySlot = widgets.some((w) => isEmptyArt(w?.art));
  const twoInRow =
    !isNarrow &&
    widgets.length >= 2 &&
    (renderableWidgets.length >= 2 || (hasExplicitEmptySlot && renderableWidgets.length >= 1));
  const standLabel = (standDerDaten != null && String(standDerDaten).trim() !== ''
    ? String(standDerDaten).trim()
    : null);
  const sectionFootnoteBlocks = collectSectionFootnoteBlocks(widgets);
  const footnoteMarginTop = renderableWidgets.some((w) => {
    const type = artToType((w.art || 'Pie Chart').trim());
    return type === 'bar-chart' || type === 'table';
  })
    ? 28
    : 8;

  return (
    <div
      className="custom-portfolio-widget"
      style={{
        marginBottom: 24,
        width: '100%',
        fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
        fontFamily: PORTFOLIO_FONT_FAMILY,
        color: PORTFOLIO_TEXT_COLOR,
      }}
    >
      {sectionTitle && (
        <div className="widget-title" style={{ marginBottom: standLabel ? 4 : 16, color }}>
          {sectionTitle}
        </div>
      )}
      {standLabel && (
        <div
          style={{
            marginBottom: 20,
            fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
            lineHeight: 1.4,
            color: PORTFOLIO_TEXT_COLOR,
            fontWeight: 400,
            fontFamily: PORTFOLIO_FONT_FAMILY,
          }}
        >
          Stand: {standLabel}
        </div>
      )}
      <div
        style={{
          display: 'flex',
          flexDirection: twoInRow ? 'row' : 'column',
          flexWrap: 'nowrap',
          gap: 24,
          alignItems: 'stretch',
          width: '100%',
        }}
      >
        {widgets.map((w, idx: number) => {
          const art = (w.art || 'Pie Chart').trim();
          if (isEmptyArt(art)) {
            if (!twoInRow) return null;
            return (
              <div
                key={idx}
                style={{
                  flex: '1 1 0',
                  minWidth: 0,
                  maxWidth: '50%',
                  boxSizing: 'border-box',
                }}
                aria-hidden
              />
            );
          }

          const rows: StyledWidgetRow[] = Array.isArray(w.rows) ? w.rows : [];
          const type = artToType(art);
          if (type === 'empty') return null;
          const renderableRows = getRenderableRowsByType(rows, type);
          if (renderableRows.length === 0) return null;
          const chartPinIdx = resolveChartPinnedRowIndex(w, rows);
          const tablePinIdx = resolveTablePinnedRowIndex(w, rows);
          const sortedRows =
            type === 'pie-chart' || type === 'bar-chart'
              ? sortRowsByMode(rows, w.sortierung, chartPinIdx >= 0 ? chartPinIdx : undefined)
              : rows;
          const title = w.title || '';
          // Slot code for the decimals override: A1 = section 0 / left, A2 = section 0 / right, …
          const slot = widgetSlotCode(sectionIndex, idx);
          const decimals = resolveWidgetDecimals(parsedTheme?.decimalsConfig, slot);

          const cellStyle: CSSProperties = twoInRow
            ? {
                flex: '1 1 0',
                minWidth: 0,
                maxWidth: '50%',
                boxSizing: 'border-box',
                overflow: type === 'table' ? 'visible' : 'hidden',
                ...(type === 'table' ? { alignSelf: 'flex-start' } : {}),
              }
            : {
                width: '100%',
                minWidth: 0,
                maxWidth: '100%',
                flex: '1 1 auto',
                alignSelf: type === 'table' ? 'flex-start' : 'stretch',
                boxSizing: 'border-box',
                overflow: type === 'table' ? 'visible' : 'hidden',
              };

          if (type === 'pie-chart') {
            const pieContent = toPieChartContent(sortedRows, decimals);
            const pieColors = getPieColorsFromTheme(parsedTheme, farbthemeFund, title);
            const themeWithColors: ITheme | undefined =
              pieColors && pieColors.length > 0
                ? (theme
                    ? { ...theme, colorSet: { ...theme.colorSet, gradientColors: pieColors } }
                    : ({ colorSet: { gradientColors: pieColors } } as ITheme))
                : theme;
            return (
              <div key={idx} style={{ ...cellStyle, alignSelf: 'flex-start', overflow: 'visible' }}>
                <CustomPortfolioPieChart content={pieContent} color={color} theme={themeWithColors} />
              </div>
            );
          }

          if (type === 'bar-chart') {
            const barColors =
              getBarColorsFromTheme(parsedTheme, farbthemeFund, title) ??
              getPieColorsFromTheme(parsedTheme, farbthemeFund, title);
            const barContent = toBarChartContent(sortedRows, title, barColors, decimals);
            const themeWithBarColors: ITheme | undefined =
              barColors && barColors.length > 0
                ? theme
                  ? { ...theme, colorSet: { ...theme.colorSet, gradientColors: barColors } }
                  : ({ colorSet: { gradientColors: barColors } } as ITheme)
                : theme;
            return (
              <div key={idx} style={cellStyle}>
                <CustomPortfolioBarChart content={barContent} color={color} theme={themeWithBarColors} />
              </div>
            );
          }

          const tableContent = toTableContent(
            rows,
            w.sortierung,
            decimals,
            tablePinIdx >= 0 ? tablePinIdx : undefined
          );
          return (
            <div key={idx} style={cellStyle}>
              <Table content={tableContent} color={color} isin={isin} theme={theme} portfolioTable />
            </div>
          );
        })}
      </div>
      {sectionFootnoteBlocks.length > 0 && (
        <div
          style={{
            marginTop: footnoteMarginTop,
            fontSize: PORTFOLIO_WIDGET_FONT_SIZE_PX,
            lineHeight: 1.4,
            whiteSpace: 'pre-wrap',
            color: PORTFOLIO_TEXT_COLOR,
            fontFamily: PORTFOLIO_FONT_FAMILY,
          }}
        >
          {sectionFootnoteBlocks.map((block, idx) => (
            <Fragment key={block.key}>
              {idx > 0 ? '\n' : null}
              {block.kind === 'runs' ? <FootnoteRuns runs={block.runs} /> : block.text}
            </Fragment>
          ))}
        </div>
      )}
    </div>
  );
}

export const CustomPortfolioWidget: FC<Props> = ({ content, color, theme, isin }) => {
  const id = content?.portfolioUploadId;
  const normalizedIsins = Array.isArray(content?.isins)
    ? content.isins.map((x) => String(x || '').trim().toUpperCase()).filter(Boolean)
    : [];
  const isNarrow = useMediaQuery('(max-width: 991px)');

  const { data, loading, error } = useQuery(GET_PORTFOLIO_UPLOAD, {
    variables: { id: id || null, isins: normalizedIsins },
    skip: !id && normalizedIsins.length === 0,
  });

  const widgetList = useMemo(() => {
    const raw = data?.getPortfolioUpload?.portfolioWidgetsData;
    if (!raw) return null;
    try {
      const list = JSON.parse(raw) as PortfolioWidgetSection[];
      return Array.isArray(list) ? list : null;
    } catch {
      return null;
    }
  }, [data?.getPortfolioUpload?.portfolioWidgetsData]);

  const parsedTheme = useMemo((): PortfolioTheme | null => {
    const raw = data?.getPortfolioUpload?.themeData;
    if (!raw) return null;
    try {
      return JSON.parse(raw) as PortfolioTheme;
    } catch {
      return null;
    }
  }, [data?.getPortfolioUpload?.themeData]);

  const farbthemeFund = data?.getPortfolioUpload?.farbthemeFund ?? '';
  const standDerDaten = data?.getPortfolioUpload?.standDerDaten ?? null;

  if (!id && normalizedIsins.length === 0) {
    return null;
  }

  if (loading) {
    return (
      <div className="widget-title" style={{ padding: 16, color }}>
        Loading portfolio data…
      </div>
    );
  }

  if (error || !widgetList) {
    return (
      <div className="widget-title" style={{ padding: 16, color }}>
        {error ? 'Failed to load portfolio data.' : 'Portfolio data not found.'}
      </div>
    );
  }

  return (
    <div style={{ width: '100%' }}>
      {widgetList.map((item, index) => (
        <PortfolioSection
          key={index}
          widgetItem={item}
          sectionIndex={index}
          parsedTheme={parsedTheme}
          farbthemeFund={farbthemeFund}
          standDerDaten={standDerDaten}
          color={color}
          theme={theme}
          isin={isin}
          isNarrow={isNarrow}
        />
      ))}
    </div>
  );
};
