import { List, ListItem, ListItemText } from '@mui/material';
import React from 'react';

type Props = {
  color: string;
  content: { label: string; url: string }[];
};

/**
 * Local inline SVG replacement for the formerly-external PDF icon.
 * The previous icon was hosted on mainfirst.tools.factsheetslive.com, whose SSL
 * certificate is no longer valid -- browsers therefore blocked the image and
 * every row showed the "document" alt-text placeholder. Using a self-contained
 * SVG makes the icon independent of any external host.
 */
const PdfIcon = ({ title = 'PDF document' }: { title?: string }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    width="20"
    height="20"
    role="img"
    aria-label={title}
    style={{ display: 'block' }}
  >
    <title>{title}</title>
    <path
      d="M6 2h8l6 6v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z"
      fill="#E2E8F0"
      stroke="#94A3B8"
      strokeWidth="1"
      strokeLinejoin="round"
    />
    <path d="M14 2v6h6" fill="#CBD5E1" stroke="#94A3B8" strokeWidth="1" strokeLinejoin="round" />
    <rect x="5.5" y="13" width="13" height="6" rx="1" fill="#D64545" />
    <text
      x="12"
      y="17.6"
      textAnchor="middle"
      fontFamily="Arial, Helvetica, sans-serif"
      fontSize="4.2"
      fontWeight="700"
      fill="#FFFFFF"
    >
      PDF
    </text>
  </svg>
);

export const DocumentList = ({ color, content }: Props) => {
  return (
    <List>
      {content.map(({ label, url }, index) => (
        <ListItem key={index}>
          <ListItemText>{label}</ListItemText>
          <ListItemText sx={{ textAlign: 'right', marginLeft: 'auto' }}>
            <a
              href={url}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={`${label} (PDF)`}
              style={{ display: 'inline-flex', alignItems: 'center', color }}
            >
              <PdfIcon title={label} />
            </a>
          </ListItemText>
        </ListItem>
      ))}
    </List>
  );
};
