/**
 * Pick readable label color (light vs dark) from a CSS background color.
 * Uses WCAG 2.1 relative luminance and contrast ratio — no per-color parser mapping.
 */

const DEFAULT_DARK = '#1a1a1a';
const DEFAULT_LIGHT = '#ffffff';

function srgbChannelToLinear(c: number): number {
  const x = c / 255;
  return x <= 0.03928 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4;
}

/** WCAG 2.1 relative luminance (0–1). */
export function relativeLuminance(r: number, g: number, b: number): number {
  const R = srgbChannelToLinear(r);
  const G = srgbChannelToLinear(g);
  const B = srgbChannelToLinear(b);
  return 0.2126 * R + 0.7152 * G + 0.0722 * B;
}

function wcagContrastRatio(lumA: number, lumB: number): number {
  const L1 = Math.max(lumA, lumB);
  const L2 = Math.min(lumA, lumB);
  return (L1 + 0.05) / (L2 + 0.05);
}

function hexToRgb(hex: string): { r: number; g: number; b: number } | null {
  const s = hex.trim().replace(/^#/, '');
  if (/^[0-9a-f]{3}$/i.test(s)) {
    const n = parseInt(s[0] + s[0] + s[1] + s[1] + s[2] + s[2], 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  if (/^[0-9a-f]{6}$/i.test(s)) {
    const n = parseInt(s, 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  return null;
}

function parseRgbCss(input: string): { r: number; g: number; b: number } | null {
  const m = input
    .trim()
    .match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i);
  if (!m) return null;
  return { r: +m[1], g: +m[2], b: +m[3] };
}

/** HSL (deg, 0–100%, 0–100%) to sRGB 0–255. */
function hslToRgb(h: number, s: number, l: number): { r: number; g: number; b: number } {
  h = ((h % 360) + 360) % 360;
  s = Math.max(0, Math.min(100, s)) / 100;
  l = Math.max(0, Math.min(100, l)) / 100;

  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;

  let rp = 0;
  let gp = 0;
  let bp = 0;
  if (h < 60) {
    rp = c;
    gp = x;
  } else if (h < 120) {
    rp = x;
    gp = c;
  } else if (h < 180) {
    gp = c;
    bp = x;
  } else if (h < 240) {
    gp = x;
    bp = c;
  } else if (h < 300) {
    rp = x;
    bp = c;
  } else {
    rp = c;
    bp = x;
  }

  return {
    r: Math.round((rp + m) * 255),
    g: Math.round((gp + m) * 255),
    b: Math.round((bp + m) * 255),
  };
}

function parseHslCss(input: string): { r: number; g: number; b: number } | null {
  const t = input.trim();
  const m = t.match(
    /^hsla?\(\s*([\d.]+)\s*(?:deg)?\s*,?\s*([\d.]+)%\s*,?\s*([\d.]+)%/i
  );
  if (m) {
    return hslToRgb(parseFloat(m[1]), parseFloat(m[2]), parseFloat(m[3]));
  }
  const m2 = t.match(/^hsla?\(\s*([\d.]+)\s+([\d.]+)%\s+([\d.]+)%/i);
  if (m2) {
    return hslToRgb(parseFloat(m2[1]), parseFloat(m2[2]), parseFloat(m2[3]));
  }
  return null;
}

export function parseCssColorToRgb(input: string): { r: number; g: number; b: number } | null {
  const t = input.trim();
  if (t.startsWith('#')) {
    return hexToRgb(t);
  }
  if (/^rgba?\(/i.test(t)) {
    return parseRgbCss(t);
  }
  if (/^hsla?\(/i.test(t)) {
    return parseHslCss(t);
  }
  return null;
}

/**
 * Returns dark or light foreground so contrast vs background is maximized (WCAG contrast ratio).
 */
export function pickContrastLabelColor(
  backgroundCss: string,
  dark: string = DEFAULT_DARK,
  light: string = DEFAULT_LIGHT
): string {
  const bgRgb = parseCssColorToRgb(backgroundCss);
  if (!bgRgb) {
    return dark;
  }
  const Lbg = relativeLuminance(bgRgb.r, bgRgb.g, bgRgb.b);

  const darkRgb = parseCssColorToRgb(dark) ?? hexToRgb(dark) ?? { r: 26, g: 26, b: 26 };
  const lightRgb = parseCssColorToRgb(light) ?? hexToRgb(light) ?? { r: 255, g: 255, b: 255 };

  const Ld = relativeLuminance(darkRgb.r, darkRgb.g, darkRgb.b);
  const Ll = relativeLuminance(lightRgb.r, lightRgb.g, lightRgb.b);

  const cDark = wcagContrastRatio(Lbg, Ld);
  const cLight = wcagContrastRatio(Lbg, Ll);

  return cDark >= cLight ? dark : light;
}
