import { FC, useMemo, CSSProperties } from 'react';
import { ArcElement, Chart as ChartJS, ChartData, ChartOptions, Legend, Tooltip, Plugin } from 'chart.js';
import ChartDataLabels, { Context } from 'chartjs-plugin-datalabels';
import { Doughnut } from 'react-chartjs-2';
import { COLOR_SETS } from '../../../contants/colors';
import { ITheme } from '.';
import { generateGradientColors } from '../../../utils/generateColorSets';
import {
  formatPortfolioValueDisplay,
  PORTFOLIO_FONT_FAMILY,
  PORTFOLIO_PIE_CHART_CANVAS_HEIGHT_PX,
  PORTFOLIO_TEXT_COLOR,
  PORTFOLIO_WIDGET_FONT_SIZE_PX,
  normalizePortfolioMultilineText,
  portfolioTooltipMaxCharsPerLine,
  portfolioLabelDisplayLines,
} from '../../../contants/portfolioTypography';

ChartJS.register(ArcElement, Tooltip, Legend, ChartDataLabels);

type Props = {
  color: string;
  content: {
    title?: string;
    subtitle?: string;
    showBlocks: boolean;
    chartData: {
      value: number;
      label: string;
      rawValue?: string;
      labelStyle?: { bold?: boolean; italic?: boolean; underline?: boolean };
      valueStyle?: { bold?: boolean; italic?: boolean; underline?: boolean };
    }[];
    /**
     * Optional decimals override from the config sheet (slot A1 / A2 / …).
     * `undefined` → keep each slice's Excel formatting (decimals only when present in source).
     */
    decimals?: number;
  };
  theme?: ITheme;
};

/** Slices below this % use outside labels + connector (number only, no "%"); larger slices use "12%" inside. */
const PIE_OUTSIDE_LABEL_THRESHOLD_PCT = 5;

/** Outside slice % + connector line — global dark blue */
const PIE_LABEL_COLOR = PORTFOLIO_TEXT_COLOR;
const PIE_INSIDE_LABEL_COLOR = '#ffffff';
/** Black outline so white % labels stay readable on any slice color (chartjs-plugin-datalabels). */
const PIE_INSIDE_LABEL_STROKE = '#000000';
const PIE_INSIDE_LABEL_STROKE_WIDTH = 2;

function getSliceSharePercent(value: number, total: number): number {
  if (total <= 0 || !Number.isFinite(value)) return 0;
  return (Math.max(value, 0) / total) * 100;
}

function isPieOutsideLabel(value: number, total: number): boolean {
  const pct = getSliceSharePercent(value, total);
  return pct > 0 && pct < PIE_OUTSIDE_LABEL_THRESHOLD_PCT;
}

const pieConnectorPlugin: Plugin<'doughnut'> = {
  id: 'customPortfolioPieConnectorPlugin',
  afterDatasetsDraw(chart) {
    const meta = chart.getDatasetMeta(0);
    const data = chart.data.datasets[0]?.data ?? [];
    if (!meta || !meta.data?.length || !data.length) return;

    const numeric = data.map((v) => Number(v) || 0);
    const total = numeric.reduce((s, v) => s + (Number.isFinite(v) ? Math.max(v, 0) : 0), 0);
    if (total <= 0) return;

    const { ctx } = chart;
    ctx.save();
    ctx.strokeStyle = PIE_LABEL_COLOR;
    ctx.lineWidth = 1;
    ctx.lineCap = 'round';

    meta.data.forEach((arc, idx: number) => {
      const a = arc as unknown as {
        startAngle: number;
        endAngle: number;
        outerRadius: number;
        x: number;
        y: number;
      };
      const value = numeric[idx];
      const pct = getSliceSharePercent(value, total);
      if (!Number.isFinite(pct) || pct >= PIE_OUTSIDE_LABEL_THRESHOLD_PCT || value <= 0) return;

      const angle = (a.startAngle + a.endAngle) / 2;
      const r1 = a.outerRadius + 2;
      const r2 = a.outerRadius + 14;
      const x1 = a.x + Math.cos(angle) * r1;
      const y1 = a.y + Math.sin(angle) * r1;
      const x2 = a.x + Math.cos(angle) * r2;
      const y2 = a.y + Math.sin(angle) * r2;

      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    });

    ctx.restore();
  },
};

/** Tooltip / full display — always with "%". */
function formatPieSlicePercent(
  val: unknown,
  decimals?: number,
  rawValue?: string
): string {
  if (rawValue != null && rawValue.trim() !== '') {
    return formatPortfolioValueDisplay(rawValue, decimals);
  }
  const num = typeof val === 'number' ? val : parseFloat(String(val).replace(',', '.'));
  if (!Number.isFinite(num)) return '';
  return formatPortfolioValueDisplay(`${num}%`, decimals);
}

/** On-chart slice label: below 5% → "3" / "1" (no "%", no decimals); 5%+ → Excel formatting. */
function formatPieSliceDataLabel(
  val: unknown,
  total: number,
  decimals?: number,
  rawValue?: string
): string {
  const num = typeof val === 'number' ? val : parseFloat(String(val).replace(',', '.'));
  if (!Number.isFinite(num)) return '';
  const sharePct = getSliceSharePercent(num, total);
  const compact = sharePct > 0 && sharePct < PIE_OUTSIDE_LABEL_THRESHOLD_PCT;
  if (compact) {
    return String(Math.round(num));
  }
  if (rawValue != null && rawValue.trim() !== '') {
    return formatPortfolioValueDisplay(rawValue, decimals);
  }
  return formatPortfolioValueDisplay(`${num}%`, decimals);
}

function getCtxValue(ctx: Context): number {
  const arr = ctx.dataset?.data as unknown[];
  const raw = Array.isArray(arr) ? arr[ctx.dataIndex] : 0;
  const n = Number(raw);
  return Number.isFinite(n) ? n : 0;
}

export const CustomPortfolioPieChart: FC<Props> = ({ color, content, theme }) => {
  const colors = (theme
    ? theme?.colorSet.gradientColors || generateGradientColors(theme?.mainColor, 8)
    : COLOR_SETS[color.toLowerCase()] || COLOR_SETS['#ccd5df']) as string[];
  const isFirstFond = color === '#ccd5df';

  const toCssFromCellStyle = (
    style?: { bold?: boolean; italic?: boolean; underline?: boolean }
  ): CSSProperties => ({
    fontWeight: style?.bold ? 700 : 400,
    fontStyle: style?.italic ? 'italic' : 'normal',
    textDecoration: style?.underline ? 'underline' : 'none',
  });

  const series = useMemo(
    () => content?.chartData?.map((item) => +item.value) || [],
    [content?.chartData]
  );

  const sliceDataLabelsOn = isFirstFond || !content.showBlocks;
  const chartData = useMemo<ChartData<'doughnut'>>(
    () => ({
      labels: content?.chartData?.map((item) => item.label) || [],
      datasets: [
        {
          data: series,
          backgroundColor: colors,
          borderWidth: 0,
          hoverOffset: 2,
          cutout: '58%',
        },
      ],
    }),
    [content, series, colors]
  );
  const total = useMemo(
    () => series.reduce((s, v) => s + (Number.isFinite(v) ? Math.max(v, 0) : 0), 0),
    [series]
  );

  const chartOptions = useMemo<ChartOptions<'doughnut'>>(
    () => ({
      font: { family: PORTFOLIO_FONT_FAMILY },
      responsive: true,
      maintainAspectRatio: false,
      layout: {
        // Extra room so small % labels around 9 / 15 o'clock stay inside the canvas (CFIF-156).
        padding: {
          top: 56,
          right: 36,
          bottom: 56,
          left: 36,
        },
      },
      plugins: {
        legend: {
          display: isFirstFond,
          position: 'right',
          labels: {
            boxWidth: 12,
            boxHeight: 12,
            color: '#333',
            font: { size: PORTFOLIO_WIDGET_FONT_SIZE_PX, family: 'inherit' },
          },
        },
        tooltip: {
          enabled: true,
          backgroundColor: 'rgba(255, 255, 255, 0.96)',
          titleColor: PIE_LABEL_COLOR,
          bodyColor: PIE_LABEL_COLOR,
          borderColor: PIE_LABEL_COLOR,
          borderWidth: 1,
          padding: 10,
          displayColors: true,
          titleFont: { family: PORTFOLIO_FONT_FAMILY, size: PORTFOLIO_WIDGET_FONT_SIZE_PX, weight: 'bold' },
          bodyFont: { family: PORTFOLIO_FONT_FAMILY, size: PORTFOLIO_WIDGET_FONT_SIZE_PX },
          callbacks: {
            title: (items) => {
              const idx = items[0]?.dataIndex ?? 0;
              const label = content?.chartData?.[idx]?.label ?? items[0]?.label ?? '';
              const chart = items[0]?.chart;
              const pieWidth = chart?.chartArea?.width ?? chart?.width ?? 280;
              const maxChars = portfolioTooltipMaxCharsPerLine(pieWidth);
              if (label.length <= maxChars && !/\n/.test(label)) return label;
              return portfolioLabelDisplayLines(label, maxChars).join('\n');
            },
            label: (ctx) => {
              const idx = ctx.dataIndex ?? 0;
              const raw = content?.chartData?.[idx]?.rawValue;
              return formatPieSlicePercent(ctx.parsed, content.decimals, raw);
            },
          },
        },
        datalabels: {
          display: (ctx: Context) => {
            if (!sliceDataLabelsOn) return false;
            const value = getCtxValue(ctx);
            const pct = getSliceSharePercent(value, total);
            return pct > 0;
          },
          color: (ctx: Context) => {
            const value = getCtxValue(ctx);
            if (isPieOutsideLabel(value, total)) return PIE_LABEL_COLOR;
            return PIE_INSIDE_LABEL_COLOR;
          },
          textStrokeColor: PIE_INSIDE_LABEL_STROKE,
          textStrokeWidth: (ctx: Context) => {
            const value = getCtxValue(ctx);
            return isPieOutsideLabel(value, total) ? 0 : PIE_INSIDE_LABEL_STROKE_WIDTH;
          },
          font: { size: PORTFOLIO_WIDGET_FONT_SIZE_PX, weight: 600, family: PORTFOLIO_FONT_FAMILY },
          formatter: (value: unknown, ctx: Context) => {
            const idx = ctx.dataIndex ?? 0;
            const raw = content?.chartData?.[idx]?.rawValue;
            return formatPieSliceDataLabel(value, total, content.decimals, raw);
          },
          anchor: (ctx: Context) => {
            const value = getCtxValue(ctx);
            return isPieOutsideLabel(value, total) ? 'end' : 'center';
          },
          align: (ctx: Context) => {
            const value = getCtxValue(ctx);
            return isPieOutsideLabel(value, total) ? 'end' : 'center';
          },
          offset: (ctx: Context) => {
            const value = getCtxValue(ctx);
            return isPieOutsideLabel(value, total) ? 10 : 0;
          },
          clamp: true,
          clip: false,
        },
      },
      animation: false,
    }),
    [isFirstFond, sliceDataLabelsOn, total, content.decimals, content?.chartData]
  );

  return (
    <>
      {content?.title && (
        <div className="widget-title" style={{ color }}>
          {content.title}
        </div>
      )}

      {content?.subtitle && (
        <div className="widget-sub-title">
          {content.subtitle}
        </div>
      )}

      <div className="pie-chart-wrapper custom-portfolio-pie-chart" lang="de">
        <div className={`pie-chart-content ${!content.showBlocks ? 'pie-chart-no-blocks' : ''}`}>
          <div
            className="pie-chart-canvas-wrap"
            style={{
              height: PORTFOLIO_PIE_CHART_CANVAS_HEIGHT_PX,
              minHeight: PORTFOLIO_PIE_CHART_CANVAS_HEIGHT_PX,
              maxHeight: PORTFOLIO_PIE_CHART_CANVAS_HEIGHT_PX,
              flexShrink: 0,
              overflow: 'hidden',
            }}
          >
            <Doughnut data={chartData} options={chartOptions} plugins={[pieConnectorPlugin]} />
          </div>

          {!isFirstFond && (
            <div className="pie-chart-legend">
              {content?.chartData?.map((item, index) => (
                <div key={index} className="pie-chart-legend-item">
                  <div style={toCssFromCellStyle(item.labelStyle)}>
                    <div className="pie-chart-legend-mark" style={{ backgroundColor: colors[index] }} />
                    <span
                      className="pie-chart-legend-label-text"
                      style={{ display: 'block', maxWidth: '100%', whiteSpace: 'pre-line' }}
                    >
                      {normalizePortfolioMultilineText(item.label)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
        {content.showBlocks && (
          <div className="pie-chart-blocks-wrapper">
            {content?.chartData.map((block, index) => (
              <div key={index} className="pie-chart-block" style={{ backgroundColor: colors[index] }}>
                <div className="block-label">
                  {formatPortfolioValueDisplay(block.rawValue ?? `${+block.value}%`, content.decimals)}
                </div>
                <div className="block-value">{block.label}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  );
};
