import { FC, useMemo, CSSProperties } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { COLOR_SETS } from '../../../contants/colors';
import { ITheme } from '.';
import { generateGradientColors } from '../../../utils/generateColorSets';
import { pickContrastLabelColor } from '../../../utils/contrastLabelColor';

type Props = {
  color: string;
  content: {
    title?: string;
    subtitle?: string;
    showBlocks: boolean;
    chartData: {
      value: number;
      label: string;
      labelStyle?: { bold?: boolean; italic?: boolean; underline?: boolean };
      valueStyle?: { bold?: boolean; italic?: boolean; underline?: boolean };
    }[];
  };
  theme?: ITheme;
};

/**
 * Hide slice % labels when the arc is narrower than this (degrees).
 * Apex shows a label only if sector angle &gt; this value (~20° ≈ 5.6% of the donut).
 */
const PIE_MIN_ANGLE_DEG_FOR_LABEL = 20;

function formatPieSlicePercent(val: unknown): string {
  const num = typeof val === 'number' ? val : parseFloat(String(val).replace(',', '.'));
  if (!Number.isFinite(num)) return '';
  const rounded = Number(num.toFixed(2));
  const s = String(rounded).replace('.', ',');
  return `${s}%`;
}

export const PieChart: FC<Props> = ({ color, content, theme }) => {
  const colors = theme
    ? theme?.colorSet.gradientColors || generateGradientColors(theme?.mainColor, 8)
    : COLOR_SETS[color.toLowerCase()] || COLOR_SETS['#ccd5df'];
  const isFirstFond = color === '#ccd5df';

  const toCssFromCellStyle = (
    style?: { bold?: boolean; italic?: boolean; underline?: boolean }
  ): CSSProperties => ({
    fontWeight: style?.bold ? 700 : 400,
    fontStyle: style?.italic ? 'italic' : 'normal',
    textDecoration: style?.underline ? 'underline' : 'none',
  });

  const series = useMemo(
    () => content?.chartData?.map((item) => +item.value) || [],
    [content?.chartData]
  );

  const sliceDataLabelsOn = isFirstFond || !content.showBlocks;

  const dataLabelColors = useMemo(
    () =>
      series.map((_, i) =>
        pickContrastLabelColor(String((colors as string[])[i % Math.max(colors.length, 1)] || '#cccccc'))
      ),
    [series, colors]
  );

  const chartData = useMemo(
    () => ({
      series,
      options: {
        labels: content?.chartData?.map((item) => item.label) || [],
        stroke: {
          width: 0,
        },
        plotOptions: {
          pie: {
            dataLabels: {
              // 0 = Apex default: label anchor sits on the donut mid-radius. Negative values pull toward the hole and look off-center on some slices.
              offset: 0,
              minAngleToShowLabel: PIE_MIN_ANGLE_DEG_FOR_LABEL,
            },
            donut: {
              customScale: 0.8,
            },
          },
        },
        dataLabels: {
          enabled: sliceDataLabelsOn,
          formatter: (val: string | number | number[]) => formatPieSlicePercent(val),
          style: {
            colors: dataLabelColors,
            fontSize: '13px',
            fontWeight: 600,
          },
          dropShadow: {
            enabled: true,
            top: 1,
            left: 0,
            blur: 2,
            opacity: 0.28,
            color: '#000000',
          },
        },
        colors,
        chart: {
          type: 'donut',
        },
        markers: {
          shape: 'square',
          size: 50,
        },
        legend: {
          show: isFirstFond,
          width: 200,
          position: 'right',
          containerMargin: {
            top: 0,
          },
          fontSize: '16px',
          fontFamily: 'inherit',
        },
        responsive: [
          {
            breakpoint: 600,
            options: {
              legend: {
                fontSize: '11px',
                position: 'bottom',
                width: '100%',
              },
              dataLabels: {
                style: {
                  fontSize: '11px',
                },
              },
            },
          },
        ],
      },
    }),
    [content, colors, color, series, sliceDataLabelsOn, dataLabelColors]
  );

  return (
    <>
      {content?.title && (
        <div className="widget-title" style={{ color }}>
          {content.title}
        </div>
      )}

      {content?.subtitle && (
        <div className="widget-sub-title">
          {content.subtitle}
        </div>
      )}

      <div className="pie-chart-wrapper">
        <div className={`pie-chart-content ${!content.showBlocks ? 'pie-chart-no-blocks' : ''}`}>
          <ReactApexChart options={chartData.options as ApexOptions} series={chartData.series} type="donut" />

          {!isFirstFond && (
            <div className="pie-chart-legend">
              {content?.chartData?.map((item, index) => (
                <div key={index} className="pie-chart-legend-item">
                  <div style={toCssFromCellStyle(item.labelStyle)}>
                    <div className="pie-chart-legend-mark" style={{ backgroundColor: colors[index] }} />
                    {item.label}
                  </div>
                  <div style={toCssFromCellStyle(item.valueStyle)}>
                    {item.value}%
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
        {content.showBlocks && (
          <div className="pie-chart-blocks-wrapper">
            {content?.chartData.map((block, index) => (
              <div key={index} className="pie-chart-block" style={{ backgroundColor: colors[index] }}>
                <div className="block-label">{(+block.value)?.toFixed(2).replace('.', ',')} %</div>
                <div className="block-value">{block.label}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  );
};
