/** Normalize Excel Alt+Enter / OOXML line breaks without collapsing manual breaks. */
export function normalizePortfolioMultilineText(raw: string): string {
  return String(raw ?? '')
    .replace(/_x000D_/gi, '\n')
    .replace(/\r\n?/g, '\n')
    .trim();
}

export function portfolioLabelHasExplicitLineBreak(label: string): boolean {
  return /\n/.test(normalizePortfolioMultilineText(label));
}

/**
 * Wraps chart labels at spaces so the line fills before breaking; long tokens without
 * spaces are split only when they exceed `maxCharsPerLine`.
 * Does not split on Excel Alt+Enter — use `portfolioLabelDisplayLines` for that.
 */
export function wrapPortfolioChartLabel(
  label: string,
  maxCharsPerLine: number = PORTFOLIO_CHART_LABEL_SINGLE_LINE_MAX_CHARS
): string[] {
  const text = normalizePortfolioMultilineText(label);
  if (!text) return [''];
  if (text.length <= maxCharsPerLine) return [text];

  const words = text.split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let current = '';

  const flush = () => {
    if (current) {
      lines.push(current);
      current = '';
    }
  };

  const appendLongToken = (token: string) => {
    let rest = token;
    while (rest.length > maxCharsPerLine) {
      if (current) flush();
      lines.push(`${rest.slice(0, maxCharsPerLine)}-`);
      rest = rest.slice(maxCharsPerLine);
    }
    current = rest;
  };

  for (const word of words) {
    if (!current) {
      if (word.length <= maxCharsPerLine) {
        current = word;
      } else {
        appendLongToken(word);
      }
      continue;
    }

    const room = maxCharsPerLine - current.length - 1;
    if (room <= 0) {
      flush();
      if (word.length <= maxCharsPerLine) {
        current = word;
      } else {
        appendLongToken(word);
      }
      continue;
    }

    if (word.length <= room) {
      current = `${current} ${word}`;
      continue;
    }

    const fragment = word.slice(0, room);
    const wordRest = word.slice(room);
    current = `${current} ${fragment}-`;
    flush();
    if (wordRest.length > maxCharsPerLine) {
      appendLongToken(wordRest);
    } else {
      current = wordRest;
    }
  }

  flush();
  return lines.length > 0 ? lines : [''];
}

/**
 * Display lines for pie/bar/table labels: honor Excel Alt+Enter first, then CFIF-156 wrap per paragraph.
 */
export function portfolioLabelDisplayLines(
  label: string,
  maxCharsPerLine: number = PORTFOLIO_CHART_LABEL_SINGLE_LINE_MAX_CHARS
): string[] {
  const text = normalizePortfolioMultilineText(label);
  if (!text) return [''];
  const lines: string[] = [];
  for (const para of text.split('\n')) {
    lines.push(...wrapPortfolioChartLabel(para, maxCharsPerLine));
  }
  return lines.length > 0 ? lines : [''];
}

/** Bar-chart labels: honor Alt+Enter, then wrap at 30 characters per line. */
export function portfolioBarChartLabelText(label: string): string {
  return portfolioLabelDisplayLines(label, PORTFOLIO_BAR_CHART_LABEL_MAX_CHARS).join('\n');
}

/** Pie tooltip: max characters per line from ~80% of the chart area width. */
export function portfolioTooltipMaxCharsPerLine(pieAreaWidthPx: number): number {
  const maxPx = Math.max(0, pieAreaWidthPx) * 0.8;
  const avgCharPx = PORTFOLIO_WIDGET_FONT_SIZE_PX * 0.55;
  return Math.max(12, Math.floor(maxPx / avgCharPx));
}

/**
 * Portfolio table column 1 (labels): aim for one line up to this many characters;
 * minimum product requirement is 34 (`PORTFOLIO_TABLE_COL1_SINGLE_LINE_MIN_CHARS`).
 */
export const PORTFOLIO_TABLE_COL1_SINGLE_LINE_TARGET_CHARS = 37;
export const PORTFOLIO_TABLE_COL1_SINGLE_LINE_MIN_CHARS = 34;

/**
 * SheetJS often emits Excel display numbers with a US decimal point (e.g. "8.0%") even when
 * the sheet uses a German locale. Rewrite only unambiguous single-decimal tokens — not dates
 * ("10.04.26"), not strings that already mix "." and "," (e.g. "1.234,5").
 */
function normalizeGermanDecimalSeparator(raw: string): string {
  const trimmed = raw.trim();
  if (trimmed === '') return raw;
  if (/,/.test(trimmed) && /\./.test(trimmed)) return raw;
  if (/^\d+\.\d+\.\d/.test(trimmed)) return raw;

  const m = trimmed.match(/^(-?\d+)\.(\d+)(\s*%)?\s*$/);
  if (!m) return raw;

  const replacement = `${m[1]},${m[2]}${m[3] ?? ''}`;
  if (raw === trimmed) return replacement;
  const leadLen = raw.length - raw.trimStart().length;
  const trailLen = raw.length - raw.trimEnd().length;
  return raw.slice(0, leadLen) + replacement + raw.slice(raw.length - trailLen);
}

/**
 * Apply the decimals override from the config sheet to a displayed value.
 *
 * - `decimals` undefined / null / negative → pass the raw value through, after normalizing
 *   a lone US-style decimal (e.g. "8.0%" → "8,0%") for German portfolio display.
 * - Non‑numeric strings (e.g. "Wert - 10.04.26") pass through unchanged.
 * - Numeric strings, with or without a trailing `%`, are rounded to the
 *   requested decimals and formatted with a German comma decimal separator.
 *   `decimals = 2` → "21%" → "21,00%", "2.845%" → "2,85%".
 *   `decimals = 0` → "2.845%" → "3%".
 */
export function applyDecimals(value: unknown, decimals?: number): string {
  const raw = value == null ? '' : String(value);
  if (decimals == null || !Number.isFinite(decimals) || decimals < 0) {
    return normalizeGermanDecimalSeparator(raw);
  }
  const trimmed = raw.trim();
  if (trimmed === '') return raw;
  const match = trimmed.match(/^(-?\d+(?:[.,]\d+)?)\s*(%?)$/);
  if (!match) return normalizeGermanDecimalSeparator(raw);
  const n = parseFloat(match[1].replace(',', '.'));
  if (!Number.isFinite(n)) return normalizeGermanDecimalSeparator(raw);
  const fixed = n.toFixed(decimals).replace('.', ',');
  return `${fixed}${match[2]}`;
}

/** Decimal places present in a single pasted value string (e.g. "5.00%" → 2). */
export function inferDecimalsFromValueString(value: unknown): number | undefined {
  const trimmed = String(value ?? '').trim();
  const match = trimmed.match(/^-?\d+[.,](\d+)\s*%?$/);
  return match ? match[1].length : undefined;
}

/** Infer decimal places from pasted portfolio value strings (e.g. "5.00%" → 2). */
export function inferDecimalsFromValueStrings(values: unknown[]): number | undefined {
  let max = -1;
  for (const value of values) {
    const n = inferDecimalsFromValueString(value);
    if (n != null) max = Math.max(max, n);
  }
  return max >= 0 ? max : undefined;
}

/**
 * Format a portfolio value for display.
 * - With `decimalsOverride` (config-sheet slot grid): always round/pad to that many places.
 * - Without override: keep Excel formatting — only show decimals when the source string has them.
 */
export function formatPortfolioValueDisplay(value: unknown, decimalsOverride?: number): string {
  const raw = value == null ? '' : String(value);
  if (decimalsOverride != null && Number.isFinite(decimalsOverride) && decimalsOverride >= 0) {
    return applyDecimals(raw, decimalsOverride);
  }
  const inferred = inferDecimalsFromValueString(raw);
  return applyDecimals(raw, inferred);
}

function resolveDecimalsFromTheme(
  decimalsConfig: Record<string, number> | undefined,
  slot: string
): number | undefined {
  if (!decimalsConfig) return undefined;
  const v = decimalsConfig[slot];
  return typeof v === 'number' && Number.isFinite(v) ? v : undefined;
}

/**
 * Resolve decimals override from the config-sheet slot grid (A1, B1, …).
 * Empty / unset slots → no global override; values keep their Excel formatting.
 */
export function resolveWidgetDecimals(
  decimalsConfig: Record<string, number> | undefined,
  slot: string
): number | undefined {
  return resolveDecimalsFromTheme(decimalsConfig, slot);
}
